import csv
import io
import re


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    def normalize(value):
        return re.sub(r"\s+", " ", value.strip()).casefold()

    header_labels = {
        "directorate", "service area", "group description", "paid date",
        "supplier name", "internal ref", "cap/rev", "cost centre",
        "cost centre name", "total",
    }

    header_index = None
    for index, record in enumerate(records):
        labels = {normalize(value) for value in record if value.strip()}
        if len(labels & header_labels) >= 3:
            header_index = index
            break

    if header_index is None:
        for index, record in enumerate(records):
            if sum(bool(value.strip()) for value in record) >= 2:
                header_index = index
                break

    if header_index is None:
        for index, record in enumerate(records):
            if any(value.strip() for value in record):
                header_index = index
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    header = records[header_index]
    rows = records[header_index + 1:]
    width = max([11, len(header)] + [len(row) for row in rows])

    columns = []
    used = set()
    for index in range(width):
        name = header[index].strip() if index < len(header) else ""
        if not name:
            name = "column_{}".format(index + 1)
        base = name
        suffix = 2
        while name.casefold() in used:
            name = "{}_{}".format(base, suffix)
            suffix += 1
        used.add(name.casefold())
        columns.append(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
